// ── Boolean algebra laws verified in JavaScript ───────────────

// De Morgan's theorems — exhaustive verification
const demorgan1 = (a, b) => !(a && b) === (!a || !b);  // always true
const demorgan2 = (a, b) => !(a || b) === (!a && !b);  // always true

for (const a of [true, false]) {
  for (const b of [true, false]) {
    console.assert(demorgan1(a, b), 'De Morgan 1 failed');
    console.assert(demorgan2(a, b), 'De Morgan 2 failed');
  }
}
console.log('De Morgan theorems hold for all inputs');

// Practical De Morgan: simplify guard clauses
function canAccess_verbose(user) {
  // Hard to read double-negation form
  if (!(user.isLoggedIn && user.hasPermission)) return false;
  return true;
}
function canAccess_clear(user) {
  // De Morgan applied: matches natural language 'if not logged in OR no permission'
  if (!user.isLoggedIn || !user.hasPermission) return false;
  return true;
}

// XOR: check if exactly one of two booleans is true
const xor = (a, b) => a !== b;
console.log(xor(true, false));   // true
console.log(xor(true, true));    // false

// Bitwise XOR to toggle specific bits
let flags = 0b1010;
flags ^= 0b0010;  // toggle bit 1
console.log(flags.toString(2));  // "1000" — bit 1 cleared
flags ^= 0b0010;  // toggle again
console.log(flags.toString(2));  // "1010" — restored

// ── Gate primitives → half adder → full adder → 4-bit adder ──

const NOT  = (a)    => a ^ 1;
const AND  = (a, b) => a & b;
const OR   = (a, b) => a | b;
const XOR  = (a, b) => a ^ b;
const NAND = (a, b) => NOT(AND(a, b));

// Half adder: 1-bit addition without carry-in
function halfAdder(a, b) {
  return { sum: XOR(a, b), carry: AND(a, b) };
}

// Full adder: 1-bit addition with carry-in
function fullAdder(a, b, cin) {
  const first  = halfAdder(a, b);
  const second = halfAdder(first.sum, cin);
  return {
    sum:   second.sum,
    carry: OR(first.carry, second.carry)
  };
}

// 4-bit ripple-carry adder
function add4bit(a4, b4) {
  let carry = 0;
  let bits = [];
  for (let i = 0; i < 4; i++) {
    const bitA = (a4 >> i) & 1;
    const bitB = (b4 >> i) & 1;
    const fa = fullAdder(bitA, bitB, carry);
    bits.push(fa.sum);
    carry = fa.carry;
  }
  bits.push(carry);  // overflow bit
  const decimal = parseInt(bits.reverse().join(''), 2);
  return { decimal, overflow: carry === 1 };
}

console.log(add4bit(0b0101, 0b0011)); // 5+3 = { decimal:8, overflow:false }
console.log(add4bit(0b1111, 0b0001)); // 15+1 = { decimal:0, overflow:true }  — wraps!

// NAND universality verification
const NAND_NOT = (a)    => NAND(a, a);
const NAND_AND = (a, b) => NAND(NAND(a,b), NAND(a,b));
const NAND_OR  = (a, b) => NAND(NAND(a,a), NAND(b,b));

console.log('OR via NAND:', NAND_OR(1, 0));   // 1
console.log('AND via NAND:', NAND_AND(1, 1)); // 1
console.log('NOT via NAND:', NAND_NOT(1));    // 0
